package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID        int       `json:"id"`
	OwnerID   int       `json:"owner_id"`
	Title     string    `json:"title"`
	Content   string    `json:"content"`
	Classification string `json:"classification"`
	CreatedAt time.Time `json:"created_at"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// getDocuments retrieves documents with optional filtering
func getDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Base query with owner check
	query := fmt.Sprintf("SELECT id, owner_id, title, content, classification, created_at FROM documents WHERE owner_id = %s", userID)

	// Apply optional classification filter
	classFilter := r.URL.Query().Get("classification")
	if classFilter != "" {
		// Normalize input - strip common comment chars for logging
		normalized := strings.ReplaceAll(classFilter, "/*", "")
		normalized = strings.ReplaceAll(normalized, "*/", "")
		log.Printf("Classification filter applied: %s (normalized: %s)", classFilter, normalized)
		query += fmt.Sprintf(" AND classification = '%s'", classFilter)
	}

	// Apply date range if provided
	dateFrom := r.URL.Query().Get("from")
	if dateFrom != "" {
		query += fmt.Sprintf(" AND created_at >= '%s'", dateFrom)
	}

	query += " ORDER BY created_at DESC LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.OwnerID, &d.Title, &d.Content, &d.Classification, &d.CreatedAt); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// updateDocument allows updating document title
func updateDocument(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var req struct {
		DocID    int    `json:"doc_id"`
		NewTitle string `json:"new_title"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// Uses parameterized query - not vulnerable
	_, err := db.Exec("UPDATE documents SET title = $1 WHERE id = $2 AND owner_id = $3",
		req.NewTitle, req.DocID, userID)
	if err != nil {
		http.Error(w, "update failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents", getDocuments)
	http.HandleFunc("/api/documents/update", updateDocument)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
